const ARABIC_ORDINALS = ['','الأولى','الثانية','الثالثة','الرابعة','الخامسة','السادسة','السابعة','الثامنة','التاسعة','العاشرة','الحادية عشرة','الثانية عشرة'];
const ARABIC_MONTHS_NUM = ['','شهر واحد','شهران','ثلاثة أشهر','أربعة أشهر','خمسة أشهر','ستة أشهر','سبعة أشهر','ثمانية أشهر','تسعة أشهر','عشرة أشهر','أحد عشر شهراً','اثنا عشر شهراً'];

const AR_MONTHS = ['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
const DAYS_AR = ['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];

function fmtDateAr(d){return `${d.getDate()} ${AR_MONTHS[d.getMonth()]} ${d.getFullYear()}`}
function fmtDateArDay(d){return `${d.getDate()} ${AR_MONTHS[d.getMonth()]} ${d.getFullYear()} (${DAYS_AR[d.getDay()]})`}
function fmtDateEn(d){return d.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}

// Arabic number words
const ON=['','واحد','اثنان','ثلاثة','أربعة','خمسة','ستة','سبعة','ثمانية','تسعة'];
const TN=['عشرة','أحد عشر','اثنا عشر','ثلاثة عشر','أربعة عشر','خمسة عشر','ستة عشر','سبعة عشر','ثمانية عشر','تسعة عشر'];
const TE=['','عشرة','عشرون','ثلاثون','أربعون','خمسون','ستون','سبعون','ثمانون','تسعون'];
const HU=['','مئة','مئتان','ثلاثمئة','أربعمئة','خمسمئة','ستمئة','سبعمئة','ثمانمئة','تسعمئة'];
function below100(n){if(n<10)return ON[n]||'';if(n<20)return TN[n-10];const t=Math.floor(n/10),o=n%10;return o?ON[o]+' و'+TE[t]:TE[t]}
function below1000(n){const h=Math.floor(n/100),r=n%100;let s=HU[h]||'';if(r){const rb=below100(r);s=s?(s+' و'+rb):rb}return s}
const THOU=['','ألف','ألفان','ثلاثة آلاف','أربعة آلاف','خمسة آلاف','ستة آلاف','سبعة آلاف','ثمانية آلاف','تسعة آلاف'];
const MIL=['','مليون','اثنان مليون','ثلاثة ملايين','أربعة ملايين','خمسة ملايين','ستة ملايين','سبعة ملايين','ثمانية ملايين','تسعة ملايين','عشرة ملايين'];
function toArWords(n){
  if(!n||n<=0)return '—';
  n=Math.round(n);
  if(n<10)return ON[n];
  if(n<100)return below100(n);
  if(n<1000)return below1000(n);
  if(n<1000000){
    const thousands=Math.floor(n/1000),rem=n%1000;
    let s='';
    if(thousands<=9)s=THOU[thousands];
    else if(thousands<20)s=TN[thousands-10]+' ألفاً';
    else if(thousands<100){const t=Math.floor(thousands/10),o=thousands%10;s=(o?ON[o]+' و':'')+TE[t]+' ألفاً';}
    else s=below1000(thousands)+' ألف';
    if(rem>0)s+=(' و'+below1000(rem));
    return s;
  }
  // Millions (designed for up to 10,000,000; falls back gracefully above)
  const millions=Math.floor(n/1000000),rem=n%1000000;
  let s=MIL[millions]||(below1000(millions)+' مليون');
  if(rem>0)s+=' و'+toArWords(rem);
  return s;
}
function toArCount(n){if(!n||n<1)return '—';n=parseInt(n);if(n<20)return [,'واحد','اثنان','ثلاثة','أربعة','خمسة','ستة','سبعة','ثمانية','تسعة','عشرة','أحد عشر','اثنا عشر','ثلاثة عشر','أربعة عشر','خمسة عشر','ستة عشر','سبعة عشر','ثمانية عشر','تسعة عشر'][n]||n.toString();return n.toString()}

