function toggleService(id){
  const card=document.getElementById('card_'+id);
  const det=document.getElementById('det_'+id);
  const active=card.classList.toggle('active');
  const isCustom=(id==='pr'||id==='ugc');
  if(active){
    det.classList.add('open');
    if(isCustom){
      // Auto-switch to manual payment mode for custom-pricing campaigns
      setMode('manual');
      setTimeout(()=>{
        const ps=document.getElementById('btnManual');
        if(ps)ps.scrollIntoView({behavior:'smooth',block:'center'});
      },200);
    }
  } else {
    det.classList.remove('open');
    if(id==='pr'){
      influencers=[];
      renderInfluencers();
    }
    if(id==='ugc'){
      ugcCreators=[];
      renderUgcCreators();
    }
    // Re-enable auto button if no custom-pricing service is active anymore
    if(isCustom && !getActiveServices().some(s=>s.id==='pr'||s.id==='ugc')){
      const btnAuto=document.getElementById('btnAuto');
      if(btnAuto){btnAuto.style.opacity='';btnAuto.style.cursor='';btnAuto.title='';}
      const notice=document.getElementById('prPmtNotice');
      if(notice)notice.style.display='none';
    }
  }
  update();
}

function getActiveServices(){return SERVICES.filter(s=>document.getElementById('card_'+s.id).classList.contains('active'))}

