function buildServicesHTML(active){
  if(!active.length)return '<li>حسب الاتفاق المُبرَم مع العميل.</li>';
  return active.map(s=>{
    const desc=document.getElementById('desc_'+s.id).value.trim();
    let extra='';
    if(s.id==='pr' && influencers.length){
      const names=influencers.map((x,i)=>`<span class="bold">${x.name||'Influencer '+(i+1)}</span>${x.handle?' ('+x.handle+')':''}`).join('، ');
      extra=`<ul class="nested-list"><li>عدد المؤثرين: <span class="bold">${influencers.length}</span></li><li>الحسابات: ${names}</li></ul>`;
    }
    if(s.id==='ugc' && ugcCreators.length){
      const names=ugcCreators.map((x,i)=>`<span class="bold">${x.name||'UGC Creator '+(i+1)}</span>${x.handle?' ('+x.handle+')':''}`).join('، ');
      extra=`<ul class="nested-list"><li>عدد صانعي المحتوى: <span class="bold">${ugcCreators.length}</span></li><li>الحسابات: ${names}</li></ul>`;
    }
    if(s.id==='mediabuy'){
      const adSpend=getMediaBuyAdSpend();
      const mbFee=getMediaBuyFee();
      const mbNote=adSpend>0
        ?`<ul class="nested-list"><li>الميزانية الإعلانية الشهرية: <span class="bold">${adSpend.toLocaleString()} EGP</span> — يدفعها العميل مباشرةً للمنصات</li><li>رسوم إدارة الإعلانات: <span class="bold">${mbFee.toLocaleString()} EGP / شهرياً</span> (20% من الإنفاق) — تُفوتَر بشكل منفصل</li></ul>`
        :`<ul class="nested-list"><li>رسوم الإدارة: <span class="bold">20% من الإنفاق الإعلاني الشهري</span> — تُفوتَر بشكل منفصل عن الدفعات الشهرية</li></ul>`;
      extra=mbNote;
    }
    return `<li><span class="bold">${s.nameAr} (${s.nameEn})</span>${desc?': '+desc:''}${extra}</li>`;
  }).join('\n        ');
}

function buildPricingTable(active,total,months){
  const mediaBuyActive=active.some(s=>s.id==='mediabuy');
  const adSpend=getMediaBuyAdSpend();
  const mbFee=getMediaBuyFee();

  const rows=active.map(s=>{
    const desc=document.getElementById('desc_'+s.id).value.trim()||'—';
    if(s.id==='mediabuy'){
      const adSpendVal=adSpend>0?adSpend.toLocaleString()+' EGP / شهرياً (يدفعه العميل مباشرة للمنصات)':'—';
      const feeVal=mbFee>0?`${mbFee.toLocaleString()} EGP / شهرياً <sup>*</sup>`:'20% من الإنفاق الإعلاني';
      return `<tr><td>${s.nameAr} (${s.nameEn})</td><td>${desc}<br><small style="color:#888">الميزانية الإعلانية: ${adSpendVal}</small></td><td>${feeVal}</td></tr>`;
    }
    const price=document.getElementById('price_'+s.id).value;
    const isOneOff=(s.id==='pr'||s.id==='ugc');
    const total=price?(isOneOff?parseInt(price):parseInt(price)*months):0;
    return `<tr><td>${s.nameAr} (${s.nameEn})</td><td>${desc}</td><td>${price?total.toLocaleString()+' EGP':'مُضمَّن في الإجمالي'}</td></tr>`;
  }).join('\n            ');

  const footnote=mediaBuyActive?`<p style="font-size:10.5px;color:#888;margin-top:8px;direction:rtl;"><sup>*</sup> رسوم إدارة الإعلانات (20% من الإنفاق الإعلاني الشهري) تُفوتَر بشكل منفصل وغير مشمولة في جدول السداد الشهري. الميزانية الإعلانية يدفعها العميل مباشرةً للمنصات.</p>`:'';

  return `<table class="pricing-table"><thead><tr><th>الخدمة</th><th>التفاصيل</th><th>القيمة (EGP)</th></tr></thead><tbody>
            ${rows}
            <tr class="total-row"><td colspan="2">الإجمالي الكلي للعقد (رسوم المحتوى)</td><td>${total.toLocaleString()} EGP</td></tr>
          </tbody></table>${footnote}`;
}

function buildPaymentTermsHTML(pmts){
  const items=pmts.map((p,i)=>{
    let whenAr;
    if(p.label){
      whenAr=`<span class="bold">${p.label}</span>`;
    } else if(i===0){
      whenAr='عند توقيع العقد';
    } else {
      whenAr=`في اليوم الخامس عشر (<span class="bold">15</span>) من شهر <span class="bold">${AR_MONTHS[p.date.getMonth()]} ${p.date.getFullYear()}</span>`;
    }
    return `<li><span class="bold">الدفعة ${ARABIC_ORDINALS[p.index]||p.index}:</span> مبلغ <span class="bold">${p.amount.toLocaleString()} جنيه مصري</span> تُسدَّد ${whenAr}، بتاريخ <span class="bold">${fmtDateAr(p.date)}</span>.</li>`;
  }).join('\n        ');
  return `<ul>\n        ${items}\n    </ul>`;
}

function buildPaymentTableHTML(pmts){
  const active=getActiveServices();
  const mediaBuyActive=active.some(s=>s.id==='mediabuy');
  const adSpend=getMediaBuyAdSpend();
  const mbFee=getMediaBuyFee();

  const rows=pmts.map((p,i)=>{
    let rowLabel;
    if(p.label){
      rowLabel=p.label;
    } else if(i===0){
      rowLabel='عند التوقيع — يوم التوقيع';
    } else {
      rowLabel=`الخامس عشر من ${AR_MONTHS[p.date.getMonth()]} ${p.date.getFullYear()}`;
    }
    return `<tr><td>${p.index}</td><td>${fmtDateAr(p.date)}<br><small style="color:#888;font-size:10px">${rowLabel}</small></td><td>${p.amount.toLocaleString()}</td><td></td><td></td></tr>`;
  }).join('\n            ');
  const total=pmts.reduce((s,p)=>s+p.amount,0);

  const mbRow=mediaBuyActive&&mbFee>0?`<tr style="background:#f9f7ff;font-size:11.5px;color:#6c56a4;">
    <td colspan="2" style="direction:rtl;text-align:right;font-weight:600;">رسوم إدارة الإعلانات (20% × ${adSpend.toLocaleString()} EGP) — مفوتَرة بشكل منفصل</td>
    <td style="font-weight:700;">${mbFee.toLocaleString()} EGP / شهرياً</td>
    <td colspan="2" style="font-size:10px;color:#888;">يُسدَّد مستقلاً</td>
  </tr>`:'';

  const footnote=mediaBuyActive?`<p style="font-size:10.5px;color:#888;margin-top:8px;direction:rtl;">ملاحظة: رسوم إدارة الإعلانات (20% من الإنفاق الإعلاني الشهري) غير مشمولة في الجدول أعلاه وتُفوتَر بشكل منفصل شهرياً. الميزانية الإعلانية يدفعها العميل مباشرةً للمنصات الإعلانية.</p>`:'';

  return `<table class="schedule-table"><thead><tr><th>#</th><th>تاريخ الاستحقاق</th><th>المبلغ (EGP)</th><th>طريقة الدفع</th><th>تأكيد الاستلام</th></tr></thead><tbody>
            ${rows}
            <tr class="total-row"><td colspan="2">إجمالي رسوم المحتوى</td><td>${total.toLocaleString()} EGP</td><td colspan="2"></td></tr>
            ${mbRow}
          </tbody></table>${footnote}`;
}

function buildSummaryTable(active){
  if(!active.length)return `<table class="pricing-table"><thead><tr><th>الخدمة</th><th>الحجم</th><th>التفاصيل</th></tr></thead><tbody><tr><td colspan="3">حسب الاتفاق</td></tr></tbody></table>`;
  const rows=active.map(s=>{
    const desc=document.getElementById('desc_'+s.id).value.trim()||'—';
    const vol=s.id==='pr'?'حملة واحدة':(s.id==='ugc'?'باقة UGC':'شهرياً');
    return `<tr><td>${s.nameAr} (${s.nameEn})</td><td>${vol}</td><td>${desc}</td></tr>`;
  }).join('\n            ');
  const infTable=active.some(s=>s.id==='pr')?buildInfluencerTableHTML():'';
  const ugcTable=active.some(s=>s.id==='ugc')?buildUgcTableHTML():'';
  return `<table class="pricing-table"><thead><tr><th>الخدمة</th><th>الحجم</th><th>التفاصيل</th></tr></thead><tbody>\n            ${rows}\n          </tbody></table>${infTable}${ugcTable}`;
}

function showWarn(msg){
  const w=document.getElementById('warn');
  w.textContent=msg||'Please fill in all required fields before generating.';
  w.classList.add('show');
}

function generate(){
  const v=getFormVals();
  const active=getActiveServices();
  document.getElementById('warn').classList.remove('show');

  if(!v.client||!v.signing||!v.months||!v.total){showWarn('Please fill in all required fields before generating.');return;}

  const startDate=new Date(v.signing);
  const endDate=new Date(startDate);
  endDate.setMonth(endDate.getMonth()+v.months);
  endDate.setDate(endDate.getDate()-1);

  // Use manual or auto payments
  let pmts;
  if (pmtMode === 'manual') {
    pmts = getManualPmts();
    if (!pmts.length) { showWarn('Add at least one payment to the manual schedule before generating.'); return; }
    const allocated = pmts.reduce((s,p)=>s+(p.amount||0),0);
    if (allocated !== v.total) {
      const diff = v.total - allocated;
      showWarn(diff>0
        ? `Manual schedule is ${diff.toLocaleString()} EGP under the contract total (${v.total.toLocaleString()} EGP). Allocate the full amount before generating.`
        : `Manual schedule is ${Math.abs(diff).toLocaleString()} EGP over the contract total (${v.total.toLocaleString()} EGP). Reduce the payments before generating.`);
      return;
    }
  } else {
    pmts = calcPayments(v.total, v.months, startDate);
  }
  const perMonth=Math.round(v.total/v.months);

  const servicesSummary=active.length?active.map(s=>s.nameEn).join(' + '):'حسب الاتفاق';
  const durationText=`${ARABIC_MONTHS_NUM[v.months]||v.months+' أشهر'} (${fmtDateEn(startDate)} → ${fmtDateEn(endDate)})`;
  const monthsText=`${ARABIC_MONTHS_NUM[v.months]||v.months+' أشهر'} (${v.months})`;
  const schedTitle=pmtMode==='manual'?`جدول السداد — مخصص (${pmts.length} دفعات)`:`جدول السداد — ${ARABIC_MONTHS_NUM[v.months]||v.months+' أشهر'}`;

  let html=TEMPLATE;
  const rep=(k,v)=>{html=html.split('{{'+k+'}}').join(v)};

  rep('CLIENT_NAME', v.client);
  rep('MAREEN_SIG_DATA_URI', MAREEN_SIG_DATA_URI);
  rep('REVISION_COST', v.revisionCost.toLocaleString());
  rep('REVISION_COST_WORDS', toArWords(v.revisionCost)+' جنيه مصري');
  rep('SHOOT_DAYS', v.shootDays);
  rep('SHOOT_DAYS_WORDS', toArWords(v.shootDays));
  rep('EXTRA_SHOOT_COST', v.extraShootCost.toLocaleString());
  rep('EXTRA_SHOOT_COST_WORDS', toArWords(v.extraShootCost)+' جنيه مصري');
  rep('SERVICES_SUMMARY', servicesSummary);
  rep('CONTRACT_DURATION_TEXT', durationText);
  rep('CONTRACT_START_DATE_COVER', fmtDateArDay(startDate));
  rep('CONTRACT_START_DATE', fmtDateAr(startDate));
  rep('CONTRACT_END_DATE', fmtDateAr(endDate));
  rep('MONTHS_DURATION_TEXT', monthsText);
  rep('TOTAL_PRICE', v.total.toLocaleString());
  rep('TOTAL_PRICE_WORDS', toArWords(v.total));
  rep('ARTICLE1_SERVICES_HTML', `<ul>\n        ${buildServicesHTML(active)}\n    </ul>`);
  rep('PRICING_TABLE_HTML', buildPricingTable(active,v.total,v.months));
  rep('PAYMENT_TERMS_HTML', buildPaymentTermsHTML(pmts));
  rep('PAYMENT_SCHEDULE_TITLE', schedTitle);
  rep('PAYMENT_TABLE_HTML', buildPaymentTableHTML(pmts));
  rep('SUMMARY_TABLE_HTML', buildSummaryTable(active));

  const blob=new Blob([html],{type:'text/html;charset=utf-8'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download='TRR-Contract-'+v.client.replace(/\s+/g,'-')+'.html';
  document.body.appendChild(a);a.click();document.body.removeChild(a);
  setTimeout(()=>URL.revokeObjectURL(url),2000);
}

